window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5cbe6b984503d078"]={"versions": [{"id": "FIG-5cbe6b984503d078", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Adaptive-Metamodell M2, <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Formale Metamodellierung der Schnittstelle <code>DiagnosticAuthenticationInterface</code> zur Definition von Diagnose-Ports für den UDS-Dienst <strong>Service 0x29 (Authentication)</strong> gemäß ISO 14229-1:2020 im AUTOSAR-Adaptive-Manifest.\n</li><li><strong>Funktionale Einordnung:</strong> Verortung im Diagnose-Subsystem der Adaptive Platform (<code>ara::diag</code>). Dient der standardisierten Entkopplung zwischen dem Diagnose-Daemon (Protokollabwicklung DoIP/CAN) und der sicherheitsrelevanten Applikations- oder Plattformlogik (z. B. PKI-Zertifikatsprüfung, Proof-of-Ownership via <code>ara::crypto</code> / HSM).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metaklassen &amp; Abstraktionsebenen:</strong>\n<ul class=\"fig-list\"><li><code>PortInterface</code> <em>(kursiv/abstrakt)</em>: Oberste Basis-Metaklasse für alle typisierten Ports im AUTOSAR-Software-Design (<code>MSR::DataDictionary::PortInterface</code>).\n</li><li><code>DiagnosticPortInterface</code> <em>(kursiv/abstrakt)</em>: Spezialisierte abstrakte Metaklasse für alle diagnosebezogenen Schnittstellen der Adaptive Platform (z. B. neben Authentication auch DataIdentifier-, Routine- oder SecurityAccess-Interfaces).\n</li><li><code>DiagnosticAuthenticationInterface</code> <em>(konkret)</em>: Konkrete Metaklasse zur Definition des Schnittstellenvertrags für Authentifizierungs-Handler (TPS_MANI_01353, TPS_MANI_01359).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Vererbung:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticAuthenticationInterface</code> ⟶ <code>DiagnosticPortInterface</code>: Generalisierung/Spezialisierung (gekennzeichnet durch geschlossene Pfeilspitze).\n</li><li><code>DiagnosticPortInterface</code> ⟶ <code>PortInterface</code>: Generalisierung/Paketebene.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Port-Typisierung:</strong>\n<ul class=\"fig-list\"><li>Im Metamodell: 1:1-Spezialisierungsbeziehung.\n</li><li>Im Systemdesign: Ein <code>DiagnosticAuthenticationInterface</code> kann von 0..* <code>PPortPrototype</code> bzw. <code>PRPortPrototype</code> referenziert werden, um die Authentifizierungsdienste für Software-Komponenten bereitzustellen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ergibt sich das dynamische Verhalten aus der zugehörigen Laufzeit-Spezifikation von <code>ara::diag</code>):</em></p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eintreffen eines UDS-Requests Service 0x29 am Diagnose-Stack (z. B. Subfunktionen: <code>verifyCertificateUnidirectional</code>, <code>verifyCertificateBidirectional</code>, <code>proofOfOwnership</code>, <code>transmitCertificate</code>).\n</li><li><strong>Dispatching:</strong> Der <code>ara::diag</code>-Daemon terminiert den Transportkanal (DoIP/SOME/IP-Diag) und leitet die Rohdaten/Zertifikate über den durch das <code>DiagnosticAuthenticationInterface</code> typisierten Port an die zuständige Anwendung weiter.\n</li><li><strong>Asynchrone Ausführung:</strong> Aufruf erfolgt typischerweise asynchron (<code>ara::core::Future</code> / Handler-Pattern), um Blockaden des Diagnose-Stacks während zeitintensiver asymmetrischer Krypto-Operationen (RSA/ECC via <code>ara::crypto</code>) zu verhindern.\n</li><li><strong>Ergebnis &amp; Statusübergang:</strong> \n<ul class=\"fig-list\"><li><em>Positiv:</em> Validierung erfolgreich → Daemon schaltet angeforderte Rollen/Rechte (White-Lists für Services/DIDs) frei und sendet positive Response (0x69).\n</li><li><em>Negativ/Abbruch:</em> Ungültige Signaturen, abgelaufene Zertifikate oder Timeouts → Rückgabe negativer Response-Codes (NRCs wie <code>0x35 InvalidKey</code>, <code>0x50 CertificateVerificationFailed</code>, <code>0x51 CertificateInstallationFailed</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Modellierung (TPS_MANI_01353, TPS_MANI_01359):</strong>\n<ul class=\"fig-list\"><li>Deklaration des <code>DiagnosticAuthenticationInterface</code> im Software-Cluster-Manifest.\n</li><li>Notwendige Zuordnung zu einem <code>DiagnosticPortMapping</code> und Verknüpfung mit der entsprechenden <code>DiagnosticServiceInstance</code> zur Konfiguration der unterstützten Subfunktionen nach ISO 14229-1:2020.\n</li></ul>\n</li><li><strong>C++ API-Generierung (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Der Manifest-Generator erzeugt aus <code>DiagnosticAuthenticationInterface</code> abstrakte C++-Klassengerüste (z. B. im Namespace <code>ara::diag::service::Authentication</code>), deren virtuelle Methoden (<code>VerifyCertificate</code>, <code>ProofOfOwnership</code>, etc.) von der Applikation überschrieben werden müssen.\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><strong>Thread-Safety &amp; Reentrancy:</strong> Handler-Methoden müssen reentrant implementiert sein, wenn parallele Diagnose-Sessions unterstützt werden.\n</li><li>**Krypto-Latenzen (P2 / P2\\* Timeouts):** Zeitaufwendige Berechnungen müssen rechtzeitig NRC 0x78 (<code>RequestCorrectlyReceived-ResponsePending</code>) durch den Stack triggern; Entwickler müssen asynchrone Bearbeitung zwingend unterstützen.\n</li><li><strong>Sicherheitsarchitektur:</strong> Trennung von Diagnose-Routing (Daemon) und kryptografischer Schlüsselverwaltung (Application/Crypto-Stack); keine Ablage von Secrets innerhalb der Schnittstellen-Payload.\n</li></ul>\n</li></ul>"}, {"id": "FIG-571e6d5579be4966", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Adaptive-Metamodell M2, <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Formale Metamodellierung der Schnittstelle <code>DiagnosticAuthenticationInterface</code> zur Definition von Diagnose-Ports für den UDS-Dienst <strong>Service 0x29 (Authentication)</strong> gemäß ISO 14229-1:2020 im AUTOSAR-Adaptive-Manifest.\n</li><li><strong>Funktionale Einordnung:</strong> Verortung im Diagnose-Subsystem der Adaptive Platform (<code>ara::diag</code>). Dient der standardisierten Entkopplung zwischen dem Diagnose-Daemon (Protokollabwicklung DoIP/CAN) und der sicherheitsrelevanten Applikations- oder Plattformlogik (z. B. PKI-Zertifikatsprüfung, Proof-of-Ownership via <code>ara::crypto</code> / HSM).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metaklassen &amp; Abstraktionsebenen:</strong>\n<ul class=\"fig-list\"><li><code>PortInterface</code> <em>(kursiv/abstrakt)</em>: Oberste Basis-Metaklasse für alle typisierten Ports im AUTOSAR-Software-Design (<code>MSR::DataDictionary::PortInterface</code>).\n</li><li><code>DiagnosticPortInterface</code> <em>(kursiv/abstrakt)</em>: Spezialisierte abstrakte Metaklasse für alle diagnosebezogenen Schnittstellen der Adaptive Platform (z. B. neben Authentication auch DataIdentifier-, Routine- oder SecurityAccess-Interfaces).\n</li><li><code>DiagnosticAuthenticationInterface</code> <em>(konkret)</em>: Konkrete Metaklasse zur Definition des Schnittstellenvertrags für Authentifizierungs-Handler (TPS_MANI_01353, TPS_MANI_01359).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Vererbung:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticAuthenticationInterface</code> ⟶ <code>DiagnosticPortInterface</code>: Generalisierung/Spezialisierung (gekennzeichnet durch geschlossene Pfeilspitze).\n</li><li><code>DiagnosticPortInterface</code> ⟶ <code>PortInterface</code>: Generalisierung/Paketebene.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Port-Typisierung:</strong>\n<ul class=\"fig-list\"><li>Im Metamodell: 1:1-Spezialisierungsbeziehung.\n</li><li>Im Systemdesign: Ein <code>DiagnosticAuthenticationInterface</code> kann von 0..* <code>PPortPrototype</code> bzw. <code>PRPortPrototype</code> referenziert werden, um die Authentifizierungsdienste für Software-Komponenten bereitzustellen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ergibt sich das dynamische Verhalten aus der zugehörigen Laufzeit-Spezifikation von <code>ara::diag</code>):</em></p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eintreffen eines UDS-Requests Service 0x29 am Diagnose-Stack (z. B. Subfunktionen: <code>verifyCertificateUnidirectional</code>, <code>verifyCertificateBidirectional</code>, <code>proofOfOwnership</code>, <code>transmitCertificate</code>).\n</li><li><strong>Dispatching:</strong> Der <code>ara::diag</code>-Daemon terminiert den Transportkanal (DoIP/SOME/IP-Diag) und leitet die Rohdaten/Zertifikate über den durch das <code>DiagnosticAuthenticationInterface</code> typisierten Port an die zuständige Anwendung weiter.\n</li><li><strong>Asynchrone Ausführung:</strong> Aufruf erfolgt typischerweise asynchron (<code>ara::core::Future</code> / Handler-Pattern), um Blockaden des Diagnose-Stacks während zeitintensiver asymmetrischer Krypto-Operationen (RSA/ECC via <code>ara::crypto</code>) zu verhindern.\n</li><li><strong>Ergebnis &amp; Statusübergang:</strong> \n<ul class=\"fig-list\"><li><em>Positiv:</em> Validierung erfolgreich → Daemon schaltet angeforderte Rollen/Rechte (White-Lists für Services/DIDs) frei und sendet positive Response (0x69).\n</li><li><em>Negativ/Abbruch:</em> Ungültige Signaturen, abgelaufene Zertifikate oder Timeouts → Rückgabe negativer Response-Codes (NRCs wie <code>0x35 InvalidKey</code>, <code>0x50 CertificateVerificationFailed</code>, <code>0x51 CertificateInstallationFailed</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Modellierung (TPS_MANI_01353, TPS_MANI_01359):</strong>\n<ul class=\"fig-list\"><li>Deklaration des <code>DiagnosticAuthenticationInterface</code> im Software-Cluster-Manifest.\n</li><li>Notwendige Zuordnung zu einem <code>DiagnosticPortMapping</code> und Verknüpfung mit der entsprechenden <code>DiagnosticServiceInstance</code> zur Konfiguration der unterstützten Subfunktionen nach ISO 14229-1:2020.\n</li></ul>\n</li><li><strong>C++ API-Generierung (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Der Manifest-Generator erzeugt aus <code>DiagnosticAuthenticationInterface</code> abstrakte C++-Klassengerüste (z. B. im Namespace <code>ara::diag::service::Authentication</code>), deren virtuelle Methoden (<code>VerifyCertificate</code>, <code>ProofOfOwnership</code>, etc.) von der Applikation überschrieben werden müssen.\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><strong>Thread-Safety &amp; Reentrancy:</strong> Handler-Methoden müssen reentrant implementiert sein, wenn parallele Diagnose-Sessions unterstützt werden.\n</li><li>**Krypto-Latenzen (P2 / P2\\* Timeouts):** Zeitaufwendige Berechnungen müssen rechtzeitig NRC 0x78 (<code>RequestCorrectlyReceived-ResponsePending</code>) durch den Stack triggern; Entwickler müssen asynchrone Bearbeitung zwingend unterstützen.\n</li><li><strong>Sicherheitsarchitektur:</strong> Trennung von Diagnose-Routing (Daemon) und kryptografischer Schlüsselverwaltung (Application/Crypto-Stack); keine Ablage von Secrets innerhalb der Schnittstellen-Payload.\n</li></ul>\n</li></ul>"}, {"id": "FIG-831f36dc8c15cbbb", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Adaptive-Metamodell M2, <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Formale Metamodellierung der Schnittstelle <code>DiagnosticAuthenticationInterface</code> zur Definition von Diagnose-Ports für den UDS-Dienst <strong>Service 0x29 (Authentication)</strong> gemäß ISO 14229-1:2020 im AUTOSAR-Adaptive-Manifest.\n</li><li><strong>Funktionale Einordnung:</strong> Verortung im Diagnose-Subsystem der Adaptive Platform (<code>ara::diag</code>). Dient der standardisierten Entkopplung zwischen dem Diagnose-Daemon (Protokollabwicklung DoIP/CAN) und der sicherheitsrelevanten Applikations- oder Plattformlogik (z. B. PKI-Zertifikatsprüfung, Proof-of-Ownership via <code>ara::crypto</code> / HSM).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metaklassen &amp; Abstraktionsebenen:</strong>\n<ul class=\"fig-list\"><li><code>PortInterface</code> <em>(kursiv/abstrakt)</em>: Oberste Basis-Metaklasse für alle typisierten Ports im AUTOSAR-Software-Design (<code>MSR::DataDictionary::PortInterface</code>).\n</li><li><code>DiagnosticPortInterface</code> <em>(kursiv/abstrakt)</em>: Spezialisierte abstrakte Metaklasse für alle diagnosebezogenen Schnittstellen der Adaptive Platform (z. B. neben Authentication auch DataIdentifier-, Routine- oder SecurityAccess-Interfaces).\n</li><li><code>DiagnosticAuthenticationInterface</code> <em>(konkret)</em>: Konkrete Metaklasse zur Definition des Schnittstellenvertrags für Authentifizierungs-Handler (TPS_MANI_01353, TPS_MANI_01359).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Vererbung:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticAuthenticationInterface</code> ⟶ <code>DiagnosticPortInterface</code>: Generalisierung/Spezialisierung (gekennzeichnet durch geschlossene Pfeilspitze).\n</li><li><code>DiagnosticPortInterface</code> ⟶ <code>PortInterface</code>: Generalisierung/Paketebene.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Port-Typisierung:</strong>\n<ul class=\"fig-list\"><li>Im Metamodell: 1:1-Spezialisierungsbeziehung.\n</li><li>Im Systemdesign: Ein <code>DiagnosticAuthenticationInterface</code> kann von 0..* <code>PPortPrototype</code> bzw. <code>PRPortPrototype</code> referenziert werden, um die Authentifizierungsdienste für Software-Komponenten bereitzustellen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ergibt sich das dynamische Verhalten aus der zugehörigen Laufzeit-Spezifikation von <code>ara::diag</code>):</em></p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eintreffen eines UDS-Requests Service 0x29 am Diagnose-Stack (z. B. Subfunktionen: <code>verifyCertificateUnidirectional</code>, <code>verifyCertificateBidirectional</code>, <code>proofOfOwnership</code>, <code>transmitCertificate</code>).\n</li><li><strong>Dispatching:</strong> Der <code>ara::diag</code>-Daemon terminiert den Transportkanal (DoIP/SOME/IP-Diag) und leitet die Rohdaten/Zertifikate über den durch das <code>DiagnosticAuthenticationInterface</code> typisierten Port an die zuständige Anwendung weiter.\n</li><li><strong>Asynchrone Ausführung:</strong> Aufruf erfolgt typischerweise asynchron (<code>ara::core::Future</code> / Handler-Pattern), um Blockaden des Diagnose-Stacks während zeitintensiver asymmetrischer Krypto-Operationen (RSA/ECC via <code>ara::crypto</code>) zu verhindern.\n</li><li><strong>Ergebnis &amp; Statusübergang:</strong> \n<ul class=\"fig-list\"><li><em>Positiv:</em> Validierung erfolgreich → Daemon schaltet angeforderte Rollen/Rechte (White-Lists für Services/DIDs) frei und sendet positive Response (0x69).\n</li><li><em>Negativ/Abbruch:</em> Ungültige Signaturen, abgelaufene Zertifikate oder Timeouts → Rückgabe negativer Response-Codes (NRCs wie <code>0x35 InvalidKey</code>, <code>0x50 CertificateVerificationFailed</code>, <code>0x51 CertificateInstallationFailed</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Modellierung (TPS_MANI_01353, TPS_MANI_01359):</strong>\n<ul class=\"fig-list\"><li>Deklaration des <code>DiagnosticAuthenticationInterface</code> im Software-Cluster-Manifest.\n</li><li>Notwendige Zuordnung zu einem <code>DiagnosticPortMapping</code> und Verknüpfung mit der entsprechenden <code>DiagnosticServiceInstance</code> zur Konfiguration der unterstützten Subfunktionen nach ISO 14229-1:2020.\n</li></ul>\n</li><li><strong>C++ API-Generierung (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Der Manifest-Generator erzeugt aus <code>DiagnosticAuthenticationInterface</code> abstrakte C++-Klassengerüste (z. B. im Namespace <code>ara::diag::service::Authentication</code>), deren virtuelle Methoden (<code>VerifyCertificate</code>, <code>ProofOfOwnership</code>, etc.) von der Applikation überschrieben werden müssen.\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><strong>Thread-Safety &amp; Reentrancy:</strong> Handler-Methoden müssen reentrant implementiert sein, wenn parallele Diagnose-Sessions unterstützt werden.\n</li><li>**Krypto-Latenzen (P2 / P2\\* Timeouts):** Zeitaufwendige Berechnungen müssen rechtzeitig NRC 0x78 (<code>RequestCorrectlyReceived-ResponsePending</code>) durch den Stack triggern; Entwickler müssen asynchrone Bearbeitung zwingend unterstützen.\n</li><li><strong>Sicherheitsarchitektur:</strong> Trennung von Diagnose-Routing (Daemon) und kryptografischer Schlüsselverwaltung (Application/Crypto-Stack); keine Ablage von Secrets innerhalb der Schnittstellen-Payload.\n</li></ul>\n</li></ul>"}, {"id": "FIG-11d4d2efc8336e02", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Ausschnitt aus dem AUTOSAR-Adaptive-Metamodell M2, <em>TPS Manifest Specification</em>).\n</li><li><strong>Technischer Zweck:</strong> Formale Metamodellierung der Schnittstellen <code>DiagnosticAuthenticationInterface</code> und <code>DiagnosticTransmitCertificateInterface</code> zur Definition von Diagnose-Ports für den UDS-Dienst <strong>Service 0x29 (Authentication)</strong> gemäß ISO 14229-1 im AUTOSAR-Adaptive-Manifest.\n</li><li><strong>Funktionale Einordnung:</strong> Verortung im Diagnose-Subsystem der Adaptive Platform (<code>ara::diag</code>). Dient der standardisierten Entkopplung zwischen dem Diagnose-Daemon (Protokollabwicklung DoIP/CAN) und der sicherheitsrelevanten Applikations- oder Plattformlogik (PKI-Zertifikatsprüfung, Proof-of-Ownership via <code>ara::crypto</code> / HSM sowie Zertifikatstransfer).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metaklassen &amp; Abstraktionsebenen:</strong>\n<ul class=\"fig-list\"><li><code>PortInterface</code> <em>(kursiv/abstrakt)</em>: Oberste Basis-Metaklasse für alle typisierten Ports im AUTOSAR-Software-Design (<code>MSR::DataDictionary::PortInterface</code>).\n</li><li><code>DiagnosticPortInterface</code> <em>(kursiv/abstrakt)</em>: Spezialisierte abstrakte Metaklasse für alle diagnosebezogenen Schnittstellen der Adaptive Platform (z. B. neben Authentication und TransmitCertificate auch DataIdentifier-, Routine- oder SecurityAccess-Interfaces).\n</li><li><code>DiagnosticAuthenticationInterface</code> <em>(konkret)</em>: Konkrete Metaklasse zur Definition des Schnittstellenvertrags für Authentifizierungs-Handler (TPS_MANI_01353, TPS_MANI_01359).\n</li><li><code>DiagnosticTransmitCertificateInterface</code> <em>(konkret)</em>: Konkrete Metaklasse zur Definition des Schnittstellenvertrags für die Übertragung von Zertifikaten im Rahmen des UDS-Dienstes 0x29 (TPS_MANI_01452).\n</li></ul>\n</li><li><strong>Beziehungen &amp; Vererbung:</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticAuthenticationInterface</code> ⟶ <code>DiagnosticPortInterface</code>: Generalisierung/Spezialisierung (gekennzeichnet durch geschlossene Pfeilspitze).\n</li><li><code>DiagnosticTransmitCertificateInterface</code> ⟶ <code>DiagnosticPortInterface</code>: Generalisierung/Spezialisierung (gekennzeichnet durch geschlossene Pfeilspitze).\n</li><li><code>DiagnosticPortInterface</code> ⟶ <code>PortInterface</code>: Generalisierung/Paketebene.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Port-Typisierung:</strong>\n<ul class=\"fig-list\"><li>Im Metamodell: 1:1-Spezialisierungsbeziehungen zu <code>DiagnosticPortInterface</code>.\n</li><li>Im Systemdesign: Sowohl <code>DiagnosticAuthenticationInterface</code> als auch <code>DiagnosticTransmitCertificateInterface</code> können von 0..* <code>PPortPrototype</code> bzw. <code>PRPortPrototype</code> referenziert werden, um die jeweiligen Authentifizierungs- und Zertifikatstransfer-Dienste für Software-Komponenten bereitzustellen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ergibt sich das dynamische Verhalten aus der zugehörigen Laufzeit-Spezifikation von <code>ara::diag</code>):</em></p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eintreffen eines UDS-Requests Service 0x29 am Diagnose-Stack (z. B. Subfunktionen: <code>verifyCertificateUnidirectional</code>, <code>verifyCertificateBidirectional</code>, <code>proofOfOwnership</code>, <code>transmitCertificate</code>).\n</li><li><strong>Dispatching:</strong> Der <code>ara::diag</code>-Daemon terminiert den Transportkanal (DoIP/SOME/IP-Diag) und leitet die Anfragen über die typisierten Ports an die zuständige Anwendung weiter:\n<ul class=\"fig-list\"><li>Authentifizierungs- und Challenge-Response-Operationen über Ports mit Typisierung durch <code>DiagnosticAuthenticationInterface</code>.\n</li><li>Zertifikatsübertragungs-Operationen (<code>transmitCertificate</code>) über Ports mit Typisierung durch <code>DiagnosticTransmitCertificateInterface</code>.\n</li></ul>\n</li><li><strong>Asynchrone Ausführung:</strong> Aufrufe erfolgen typischerweise asynchron (<code>ara::core::Future</code> / Handler-Pattern), um Blockaden des Diagnose-Stacks während zeitintensiver asymmetrischer Krypto-Operationen (RSA/ECC via <code>ara::crypto</code>) oder Zertifikatsspeicherung zu verhindern.\n</li><li><strong>Ergebnis &amp; Statusübergang:</strong> \n<ul class=\"fig-list\"><li><em>Positiv:</em> Validierung bzw. Zertifikatsübertragung erfolgreich → Freischaltung von Rollen/Rechten oder Quittierung und Senden der positiven Response (0x69).\n</li><li><em>Negativ/Abbruch:</em> Ungültige Signaturen, Übertragungsfehler, abgelaufene Zertifikate oder Timeouts → Rückgabe negativer Response-Codes (NRCs wie <code>0x35 InvalidKey</code>, <code>0x50 CertificateVerificationFailed</code>, <code>0x51 CertificateInstallationFailed</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Modellierung (TPS_MANI_01353, TPS_MANI_01359, TPS_MANI_01452):</strong>\n<ul class=\"fig-list\"><li>Deklaration von <code>DiagnosticAuthenticationInterface</code> und <code>DiagnosticTransmitCertificateInterface</code> im Software-Cluster-Manifest.\n</li><li>Notwendige Zuordnung zu einem <code>DiagnosticPortMapping</code> und Verknüpfung mit der entsprechenden <code>DiagnosticServiceInstance</code> zur Konfiguration der unterstützten Subfunktionen nach ISO 14229-1:2020.\n</li></ul>\n</li><li><strong>C++ API-Generierung (<code>ara::diag</code>):</strong>\n<ul class=\"fig-list\"><li>Der Manifest-Generator erzeugt aus <code>DiagnosticAuthenticationInterface</code> und <code>DiagnosticTransmitCertificateInterface</code> abstrakte C++-Klassengerüste (z. B. im Namespace <code>ara::diag::service</code>), deren virtuelle Methoden (<code>VerifyCertificate</code>, <code>ProofOfOwnership</code>, Zertifikatstransfer-Handler etc.) von der Applikation überschrieben werden müssen.\n</li></ul>\n</li><li><strong>Entwickler-Restriktionen:</strong>\n<ul class=\"fig-list\"><li><strong>Thread-Safety &amp; Reentrancy:</strong> Handler-Methoden müssen reentrant implementiert sein, wenn parallele Diagnose-Sessions unterstützt werden.\n</li><li>**Krypto-Latenzen (P2 / P2\\* Timeouts):** Zeitaufwendige Berechnungen müssen rechtzeitig NRC 0x78 (<code>RequestCorrectlyReceived-ResponsePending</code>) durch den Stack triggern; Entwickler müssen asynchrone Bearbeitung zwingend unterstützen.\n</li><li><strong>Sicherheitsarchitektur:</strong> Trennung von Diagnose-Routing (Daemon) und kryptografischer Schlüsselverwaltung (Application/Crypto-Stack); keine Ablage von Secrets innerhalb der Schnittstellen-Payload.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-5cbe6b984503d078", "to": "FIG-571e6d5579be4966", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-571e6d5579be4966", "to": "FIG-831f36dc8c15cbbb", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-831f36dc8c15cbbb", "to": "FIG-11d4d2efc8336e02", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>DiagnosticTransmitCertificateInterface</code>: Metaklasse neu hinzugefügt (Spezialisierung von <code>DiagnosticPortInterface</code>).\n</li><li><code>DiagnosticPortInterface</code>: Generalisierungshierarchie um die Spezialisierung durch <code>DiagnosticTransmitCertificateInterface</code> erweitert.\n</li></ul>"}]};
